import json

def parse_json(json_string, target_key, target_type):
    try:
        data = json.loads(json_string)
        return data[target_key] if isinstance(data[target_key], target_type) else None
    except json.JSONDecodeError:
        return None
    except KeyError:
        return None
    except TypeError:
        return None
